1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// node is one immutable version in a key's history. Versions form a linked
16	// list from newest to oldest; a snapshot pins the head current when it was
17	// acquired, so overwritten and deleted values stay readable through every
18	// view that references them.
19	type node struct {
20		value   []byte
21		present bool // false marks a delete; a present nil/empty value is still a hit
22		older   *node
23	}
24	
25	// view is an immutable map of keys to their newest version. Updates produce a
26	// fresh map; the current view and every snapshot simply point at one. Views
27	// are never mutated after publication, so reading them needs no lock. The
28	// maps share version chains with their successor views.
29	type view map[string]*node
30	
31	// Store is an open key-value store backed by a directory on disk.
32	type Store struct {
33		mu sync.Mutex // serializes writers and guards the fields below
34	
35		dir       string
36		wal       *walWriter
37		current   atomic.Pointer[view] // latest committed view; lock-free for readers
38		snapshots atomic.Uint64        // cumulative number of snapshots handed out
39	
40		closed atomic.Bool
41	}
42	
43	// Snapshot is a stable read-only view of a store captured at one instant. It
44	// owns no store resources and stays usable after the store has been closed.
45	type Snapshot struct {
46		v atomic.Pointer[view] // nil once the snapshot is closed
47	}
48	
49	// Open opens or creates a persistent store in dir. A path that names a
50	// regular file rather than a directory returns an error wrapping
51	// fs.ErrInvalid.
52	func Open(dir string) (*Store, error) {
53		info, err := os.Stat(dir)
54		if err == nil {
55			if !info.IsDir() {
56				return nil, errNotDir
57			}
58		} else {
59			if !errors.Is(err, fs.ErrNotExist) {
60				return nil, err
61			}
62			if err := os.MkdirAll(dir, 0o700); err != nil {
63				return nil, err
64			}
65		}
66	
67		// A replacement log from a compaction killed before its rename can never
68		// be complete state of record; the old wal.log is. Drop the stale file.
69		if err := removeStaleCompact(dir); err != nil {
70			return nil, err
71		}
72	
73		latest := make(view)
74		validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte) {
75			switch op {
76			case opPut:
77				latest[key] = &node{value: cloneBytes(value), present: true, older: latest[key]}
78			case opDelete:
79				latest[key] = &node{present: false, older: latest[key]}
80			}
81		})
82		if err != nil {
83			return nil, err
84		}
85	
86		wal, err := openWALWriter(dir, validSize)
87		if err != nil {
88			return nil, err
89		}
90	
91		s := &Store{dir: dir, wal: wal}
92		s.snapshots.Store(snapshotCount)
93		s.current.Store(&latest)
94		return s, nil
95	}
96	
97	// Put stores value under key. An empty key returns an error wrapping
98	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
99	// key reports a hit. The store does not keep a reference to value.
100	func (s *Store) Put(key string, value []byte) error {
101		s.mu.Lock()
102		defer s.mu.Unlock()
103		if s.closed.Load() {
104			return errStoreClosed
105		}
106		if key == "" {
107			return errEmptyKey
108		}
109		if err := s.wal.appendPut(key, value); err != nil {
110			return err
111		}
112		next := s.deriveView()
113		next[key] = &node{value: cloneBytes(value), present: true, older: (*s.current.Load())[key]}
114		s.current.Store(&next)
115		return nil
116	}
117	
118	// Get returns the latest committed value for key. Empty keys, keys never
119	// written and deleted keys are all misses: ok is false and err is nil. The
120	// returned bytes are owned by the caller.
121	func (s *Store) Get(key string) ([]byte, bool, error) {
122		if s.closed.Load() {
123			return nil, false, errStoreClosed
124		}
125		if key == "" {
126			return nil, false, nil
127		}
128		val, ok := lookup(*s.current.Load(), key)
129		return val, ok, nil
130	}
131	
132	// Delete removes key. Deleting an empty key returns an error wrapping
133	// fs.ErrInvalid; deleting a key that was never written or is already deleted
134	// is not an error and commits nothing.
135	func (s *Store) Delete(key string) error {
136		s.mu.Lock()
137		defer s.mu.Unlock()
138		if s.closed.Load() {
139			return errStoreClosed
140		}
141		if key == "" {
142			return errEmptyKey
143		}
144		cur := *s.current.Load()
145		if n := cur[key]; n == nil || !n.present {
146			return nil // nothing live to delete: idempotent no-op
147		}
148		if err := s.wal.appendDelete(key); err != nil {
149			return err
150		}
151		next := s.deriveView()
152		next[key] = &node{present: false, older: cur[key]}
153		s.current.Store(&next)
154		return nil
155	}
156	
157	// deriveView returns a shallow, mutable copy of the current view. Callers
158	// must hold s.mu and publish the result through s.current before unlocking.
159	func (s *Store) deriveView() view {
160		cur := *s.current.Load()
161		next := make(view, len(cur)+1)
162		for k, v := range cur {
163			next[k] = v
164		}
165		return next
166	}
167	
168	// Compact reclaims history: values that were overwritten or deleted and are
169	// not needed by any open snapshot are dropped from memory and the write-ahead
170	// log is atomically rewritten with just the live state, so the directory
171	// occupies less space than before whenever reclaimable history existed.
172	//
173	// Every open snapshot keeps its exact fixed view: its values are untouched
174	// and reads before and after compaction return byte-identical results. A
175	// process killed at any point during compaction reopens in a complete commit
176	// state, with every successful write, deletion and the cumulative snapshot
177	// count intact; no intermediate file requires a second compaction to repair.
178	//
179	// Compact takes no arguments, may be called at any time and serializes with
180	// writes, deletes, snapshots, closing and other compactions; concurrent or
181	// repeated calls queue and all return nil. Compacting a closed store returns
182	// an error wrapping fs.ErrClosed.
183	func (s *Store) Compact() error {
184		s.mu.Lock()
185		defer s.mu.Unlock()
186		if s.closed.Load() {
187			return errStoreClosed
188		}
189	
190		cur := *s.current.Load()
191		live := make([]kvEntry, 0, len(cur))
192		fresh := make(view, len(cur))
193		for k, n := range cur {
194			if !n.present {
195				continue // deleted: no live value and no version any new view needs
196			}
197			// A single-node history makes the old chain unreachable from the
198			// current view; open snapshots keep pointing at their own views, so
199			// only versions nobody reads become garbage.
200			fresh[k] = &node{value: n.value, present: true}
201			live = append(live, kvEntry{key: k, value: n.value})
202		}
203	
204		// The rewrite is crash-atomic: on return either the old log or the fully
205		// built new log is wal.log. Swapping the writer under s.mu means a
206		// concurrent writer cannot straddle the two files. A non-nil nextWAL
207		// means the rename landed even if the final directory sync reported an
208		// error; adopt it (the old file is unlinked) and publish the matching
209		// view, then surface the sync error.
210		nextWAL, compactErr := compactWAL(s.dir, live, s.snapshots.Load())
211		if nextWAL == nil {
212			return compactErr
213		}
214		oldWAL := s.wal
215		s.wal = nextWAL
216		s.current.Store(&fresh)
217		if err := oldWAL.close(); err != nil && compactErr == nil {
218			return err
219		}
220		return compactErr
221	}
222	
223	// Snapshot acquires a stable view. It never observes writes committed after
224	// it returns, and keeps serving that view regardless of later writes,
225	// deletes or Store.Close, until the Snapshot itself is closed.
226	func (s *Store) Snapshot() (*Snapshot, error) {
227		s.mu.Lock()
228		defer s.mu.Unlock()
229		if s.closed.Load() {
230			return nil, errStoreClosed
231		}
232		count := s.snapshots.Add(1)
233		if err := s.wal.appendMeta(count); err != nil {
234			s.snapshots.Add(^uint64(0))
235			return nil, err
236		}
237		snap := &Snapshot{}
238		snap.v.Store(s.current.Load())
239		return snap, nil
240	}
241	
242	// Get reads key from the snapshot's fixed view. Old values overwritten or
243	// deleted afterwards are still readable; keys created afterwards, empty
244	// keys and keys absent or deleted when the snapshot was taken are misses. A
245	// read from a closed snapshot is also a plain miss, never an error. The
246	// returned bytes are owned by the caller.
247	func (s *Snapshot) Get(key string) ([]byte, bool) {
248		if key == "" {
249			return nil, false
250		}
251		v := s.v.Load()
252		if v == nil {
253			return nil, false // closed snapshot
254		}
255		n := (*v)[key]
256		if n == nil || !n.present {
257			return nil, false
258		}
259		return cloneBytes(n.value), true
260	}
261	
262	// Close releases the snapshot's fixed view. Closing more than once is a
263	// no-op returning nil.
264	func (s *Snapshot) Close() error {
265		s.v.Store(nil)
266		return nil
267	}
268	
269	// Close flushes and closes the store. Data already committed stays complete
270	// and readable after reopening the directory. Snapshots still open keep
271	// serving their fixed views until closed themselves; closing an already
272	// closed store is a no-op returning nil.
273	func (s *Store) Close() error {
274		s.mu.Lock()
275		if !s.closed.CompareAndSwap(false, true) {
276			s.mu.Unlock()
277			return nil
278		}
279		wal := s.wal
280		s.wal = nil
281		s.mu.Unlock()
282	
283		return wal.close()
284	}
285	
286	func lookup(v view, key string) ([]byte, bool) {
287		n := v[key]
288		if n == nil || !n.present {
289			return nil, false
290		}
291		return cloneBytes(n.value), true
292	}
293	
294	func cloneBytes(b []byte) []byte {
295		if b == nil {
296			return nil
297		}
298		c := make([]byte, len(b))
299		copy(c, b)
300		return c
301	}
