1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11	)
12	
13	// On-disk write-ahead log.
14	//
15	// Every successful Put/Delete (and every successfully acquired Snapshot) is
16	// appended as one framed record and forced to stable storage before the call
17	// reports success, so reopening a directory always replays a prefix of
18	// complete records (never a half-written value) and the cumulative snapshot
19	// count is never reset.
20	//
21	// Frame layout, little-endian:
22	//
23	//	magic    uint32   recordMagic
24	//	op       byte     opPut, opDelete or opMeta
25	//	keyLen   uint32
26	//	valLen   uint32
27	//	key      [keyLen]byte
28	//	value    [valLen]byte (absent for deletes)
29	//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
30	//
31	// An opMeta record carries no key and an 8-byte little-endian value holding
32	// the cumulative number of snapshots handed out so far.
33	const (
34		walName = "wal.log"
35		// compactTmpName holds a freshly built log during compaction; it is
36		// atomically renamed over wal.log and never observed directly. A file by
37		// this name left behind by a crash mid-compaction is stale and removed on
38		// the next open.
39		compactTmpName = "wal.log.compact"
40	
41		recordMagic uint32 = 0x534e4150 // "SNAP"
42		opPut       byte   = 1
43		opDelete    byte   = 2
44		opMeta      byte   = 3
45	
46		frameHeaderSize = 4 + 1 + 4 + 4
47		crcSize         = 4
48		metaValueSize   = 8
49		maxRecord       = 1 << 30 // sanity bound on key and value lengths
50	)
51	
52	type walWriter struct {
53		f *os.File
54		w *bufio.Writer
55	}
56	
57	func openWALWriter(dir string, replaySize int64) (*walWriter, error) {
58		f, err := os.OpenFile(dir+string(os.PathSeparator)+walName, os.O_RDWR|os.O_CREATE, 0o600)
59		if err != nil {
60			return nil, err
61		}
62		// Drop any torn tail that replay could not consume. A negative replaySize
63		// means the file is already exactly what should be on disk (e.g. a log
64		// just installed by compaction) and must not be truncated.
65		if replaySize >= 0 {
66			if err := f.Truncate(replaySize); err != nil {
67				f.Close()
68				return nil, err
69			}
70		}
71		if _, err := f.Seek(0, io.SeekEnd); err != nil {
72			f.Close()
73			return nil, err
74		}
75		return &walWriter{f: f, w: bufio.NewWriter(f)}, nil
76	}
77	
78	func (l *walWriter) writeFrame(op byte, key string, value []byte) error {
79		if err := l.encodeFrame(op, key, value); err != nil {
80			return err
81		}
82		if err := l.w.Flush(); err != nil {
83			return err
84		}
85		return l.f.Sync()
86	}
87	
88	// encodeFrame buffers one framed record. Used for ordinary appends (followed
