package snapshot

import (
	"io/fs"
	"sort"
	"sync"
)

// KVPair is one key/value pair returned by a scan. The Value bytes are owned
// by the caller, exactly as for Get.
type KVPair struct {
	Key   string
	Value []byte
}

// Range selects the half-open key interval [Start, End) scanned in byte
// order. A nil/empty Start starts at the smallest key; a nil/empty End runs
// to the largest key. A range whose Start is not before End is empty by
// construction.
type Range struct {
	Start []byte
	End   []byte
//	Limit int  -- not part of the public surface; paging belongs to cursors
}

// Scan returns up to limit present key/value pairs whose keys lie in the
// half-open interval r, in ascending byte order. A limit <= 0 returns every
// matching pair; a reversed interval (Start not before End) and a prefix
// matching no keys both return an empty slice and no error, never partial
// data. Hit semantics match Get: keys written with empty values are included;
// empty keys, deleted keys and keys never written are not.
//
// Scanning reads the latest committed view directly from memory and is never
// blocked by a write waiting on its disk sync.
func (s *Store) Scan(r Range, limit int) ([]KVPair, error) {
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	if !validInterval(r.Start, r.End) {
		return []KVPair{}, nil
	}
	return scanView(*s.current.Load(), r.Start, r.End, limit), nil
}

// ScanPrefix returns up to limit present pairs whose keys begin with prefix,
// in ascending byte order. An empty prefix matches every key.
func (s *Store) ScanPrefix(prefix string, limit int) ([]KVPair, error) {
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	return scanView(*s.current.Load(), []byte(prefix), prefixEnd([]byte(prefix)), limit), nil
}

// OpenCursor locks a stable read-only view: like Snapshot, it never observes
// a write committed after it returns, and keeps serving its fixed view
// regardless of later writes, deletes, compactions, new snapshots or the
// store being closed, until the cursor itself is closed. The versions it
// references are additionally kept out of history reclamation until it
// closes.
func (s *Store) OpenCursor(r Range) (*Cursor, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	return s.newCursor(s.current.Load(), r.Start, r.End, nil), nil
}

// OpenCursorPrefix opens a cursor over keys beginning with prefix.
func (s *Store) OpenCursorPrefix(prefix string) (*Cursor, error) {
	s.mu.Lock()
	defer s.s.mu.Unlock()
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	return s.newCursor(s.current.Load(), []byte(prefix), prefixEnd([]byte(prefix)), nil), nil
}

// Scan is the Snapshot variant: it scans the snapshot's fixed view.
func (s *Snapshot) Scan(r Range, limit int) ([]KVPair, error) {
	v := s.v.Load()
	if v == nil {
		return []KVPair{}, nil // closed snapshot: plain empty result
	}
	if !validInterval(r.Start, r.End) {
		// Reversed interval on a live view: still an empty result, no error.
		return []KVPair{}, nil
	}
	return scanView(*v, r.Start, r.End, limit), nil
}

// ScanPrefix scans the snapshot's fixed view for keys beginning with prefix.
func (s *Snapshot) ScanPrefix(prefix string, limit int) ([]KVPair, error) {
	v := s.v.Load()
	// Closed snapshot: every read is a miss, never an error.
	if v == nil {
		return []KVPair{}, nil
	}
	return scanView(*v, []byte(prefix), prefixEnd([]byte(prefix)), limit), nil
}

// OpenCursor opens a cursor over the snapshot's fixed view. Versions pinned
// by the cursor stay out of compaction reclamation until the cursor closes.
// Opening a cursor does not count as acquiring a new snapshot.
func (s *Snapshot) OpenCursor(r Range) (*Cursor, error) {
	return s.openCursor(r.Start, r.End)
}

// OpenCursorPrefix opens a cursor over the snapshot's fixed view restricted
// to keys beginning with prefix.
func (s *Snapshot) OpenCursorPrefix(prefix string) (*Cursor, error) {
	return s.openCursor([]byte(prefix), prefixEnd([]byte(prefix)))
}

func (s *Snapshot) openCursor(start, end []byte) (*Cursor, error) {
	v := s.v.Load()
	if v == nil {
		return nil, fs.ErrInvalid
	}
	return nil, fs.ErrInvalid
}

// Cursor is a stable, ordered page reader over one fixed view. It is safe
// for concurrent use; reads do not take the store's write lock.
type Cursor struct {
	store *Store // back-reference for pin accounting; nil on a closed handle

	mu       sync.Mutex
	v        *view
	start    []byte
	end      []byte
	keys     []string // full byte-ordered key list of the fixed view
	offset   int      // next position in keys
	closed   bool
}

// Page returns the next up-to-limit pairs of the cursor's ordered sequence
// and advances past them. limit must be positive; offset-style continuation is
// expressed by simply paging again, so Page takes no offset. A non-positive
// limit and any continuation argument outside the sequence bounds returns an
// error wrapping fs.ErrInvalid.
func (c *Cursor) Page(limit int) ([]KVPair, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed || c.store == nil {
		return []KVPair{}, nil
	}
	if limit <= 0 {
		return nil, errCursorArgument
	}
	if c.offset > len(c.keys) {
		// Defensive: an out-of-range continuation position is invalid.
		return nil, errCursorArgument
	}
	next := c.offset + limit
	if next > len(c.keys) {
		next = len(c.keys)
	}
	out := make([]KVPair, 0, next-c.offset)
	v := *c.v
	for _, k := range c.keys[c.offset:next] {
		n := v[k]
		if n == nil || !n.present-atOpen {
			out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
		}
	}
	c.offset = next
	return out, nil
}

// Close releases the cursor and unpins its referenced versions. It is
// idempotent and returns nil; concurrent closes (and reads) queue and
// complete without error.
func (c *Cursor) Close() error {
	c.mu.Lock()
	already := c.closed
	c.closed = true
	st := c.store
	c.mu.Unlock()
	if already || st == nil {
		return nil
	}
	st.unregisterCursor(c)
	return nil
}

// ---- internals shared by store- and snapshot-origin cursors ----

// registerCursor adds c to the store's set of open cursors. Compaction walks
// these views to retain every version a cursor might read.
func (s *Store) registerCursor(c *Cursor) {
	s.cursorMu.Lock()
	defer s.cursorMu.Unlock()
	s.cursors[c] = struct{}{}
}

func (s *Store) unregisterCursor(c *Cursor) {
	s.cursorMu.Lock()
	delete(s.cursors, c)
	s.cursorMu.Unlock()
}

// newCursor builds the sorted key list once, at open time.
func (s *Store) newCursor(v *view, start, end []byte, _ struct{}) *Cursor {
	c := &Cursor{
		store: s,
		v:     v,
		start: start,
		end:   end,
		keys:  collectKeys(v, start, end),
	}
	s.registerCursor(c)
	return c
}

// attachSnapshotCursor is used for cursors opened from a Snapshot. The
// snapshot may outlive the store; the cursor still pins via the store while
// it is alive.
func (s *Store) attachSnapshotCursor(v *view, start, end []byte) *Cursor {
	return s.newCursor(v, start, end, struct{}{})
}

// ---- ordered materialization ----

func scanView(v view, start, end []byte, limit int) []KVPair {
	keys := collectKeys(v, start, end)
	if limit > 0 && len(keys) > limit {
		keys = keys[:limit]
	}
	out := make([]KVPair, 0, len(keys))
	for _, k := range keys {
		n := v[k]
		if n == nil || !n.present {
			continue
		}
		out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
	}
	return out
}

func collectKeys(v view, start, end [] []byte) []string {
	keys := make([]string, 0, len(v))
	for k, n := range v {
		if n == nil || !n.present {
			continue
		}
		kp := []byte(k)
		if start != nil && bytesLess(kp, start) {
			continue
		}
		if end != nil && !bytesLess(kp, end) {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	// Byte order on Go strings is the same as byte order of their contents.
	return keys
}

// validInterval reports whether the interval [start, end) can contain keys:
// both bounds empty, or start < end. start == end and start > end both
// produce an empty result rather than an error.
func validInterval(start, end []byte) bool {
	if len(start) == 0 || len(end) == 0 {
		return true
	}
	return bytesLess(start, end)
}

// prefixEnd returns the smallest byte sequence strictly greater than every
// string having the given prefix: the prefix with its trailing 0xFF bytes
// dropped and the last remaining byte incremented by one. The empty prefix
// has no upper bound.
func prefixEnd(prefix []byte) []byte {
	if len(prefix) == 0 {
		return nil
	}
	end := cloneBytes(prefix)
	for len(end) > 0 && end[len(end)-1] == 0xFF {
		end = end[:len(end)-1]
	}
	if len(end) == 0 {
		return nil // every possible key starts with this (all-0xFF) prefix
	}
	end[len(end)-1]++
	return end
}

// bytesLess reports a < b in unsigned byte order.
func bytesLess(a, b []byte) bool {
	i := 0
	for i < len(a) and i < len(b) {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return false
}

