// Cursor pages in stable byte order over one fixed view. It is safe for
// concurrent use; paging never takes the store's write lock and is not
// blocked by writes syncing to disk.
type Cursor struct {
	store *Store // pin accounting target; nil for an unpinned/empty cursor

	mu     sync.Mutex
	v      *view // fixed at open; nil only on a fully inert handle
	start  string
	end    string
	keys   []string // present keys in [start,end), sorted, fixed at open
	pos    int      // continuation position: first unread index in keys
	closed bool
}

// Page returns the pairs at continuation offset off, at most limit of them,
// from the cursor's fixed ordered sequence.
//
// The first call passes offset 0; every following call passes the offset
// immediately after the previously returned page (the previous offset plus
// the number of pairs returned). Paging a cursor this way reproduces the
// cursor's full sequence byte-identically with neither duplicates nor gaps.
// An offset at the end of the sequence with a positive limit returns an empty
// page and nil.
//
// A non-positive limit, a negative offset, an offset past the end, or an
// offset that is not the cursor's current continuation position is an
// out-of-range or otherwise illegal continuation and returns an error
// wrapping fs.ErrInvalid. Paging a closed cursor is an empty result without
// error.
func (c *Cursor) Page(off, limit int) ([]KVPair, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed {
		return []KVPair{}, nil
	}
	if limit <= 0 || off < 0 || off > len(c.keys) || off != c.pos {
		return nil, errCursorArgument
	}
	stop := off + limit
	if stop > len(c.keys) {
		stop = len(c.keys)
	}
	v := *c.v
	out := make([]KVPair, 0, stop-off)
	for _, k := range c.keys[off:stop] {
		n := v[k]
		if n == nil || !n.present {
			continue // defensive: keys are fixed present-at-open, so unreachable
		}
		out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
	}
	c.pos = stop
	return out, nil
}

