func TestLegacyWALReopens(t *testing.T) {
	// Hand-write a log using the original, seq-less frame format; scan and
	// pagination over a reopened old-version directory must work unchanged.
	dir := tempDir(t)
	if err := mkdir700(dir); err != nil {
		t.Fatal(err)
	}
	var buf bytes.Buffer
	appendLegacy := func(op byte, key string, value []byte) {
		hdr := make([]byte, frameHeaderSize)
		hdr[0] = byte(recordMagic)
		hdr[1] = byte(recordMagic >> 8)
		hdr[2] = byte(recordMagic >> 16)
		hdr[3] = byte(recordMagic >> 24)
		hdr[4] = op
		binaryPutUint32(hdr[5:], uint32(len(key)))
		binaryPutUint32(hdr[9:], uint32(len(value)))
		buf.Write(hdr)
		buf.WriteString(key)
		buf.Write(value)
		// crc32 IEEE over hdr+key+value
		body := append(append(append([]byte{}, hdr...), key...), value...)
		crc := crc32Checksum(body)
		var crcb [4]byte
		binaryPutUint32(crcb[:], crc)
		buf.Write(crcb[:])
	}
	appendLegacy(opPut, "a", []byte("1"))
	appendLegacy(opPut, "b", []byte("2"))
	appendLegacy(opDelete, "b", nil)
	if err := writeFile600(filepath.Join(dir, walName), buf.Bytes()); err != nil {
		t.Fatal(err)
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	pairs, err := s.Scan(Range{}, 0)
	if err != nil || len(pairs) != 1 || pairs[0].Key != "a" || string(pairs[0].Value) != "1" {
		t.Fatalf("legacy scan: %+v err=%v", pairs, err)
	}
	// New writes interleave with legacy history; overwrites + compact work.
	if err := s.Put("a", []byte("9")); err != nil {
		t.Fatal(err)
	}
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	if got, ok, _ := s.Get("a"); !ok || string(got) != "9" {
		t.Fatalf("post-legacy overwrite: %q %v", got, ok)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	if got, ok, _ := s2.Get("a"); !ok || string(got) != "9" {
		t.Fatalf("legacy chain after reopen: %q %v", got, ok)
	}
}

func sliceEq(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

